-- Exile's Reach: spawns seen in the retail sniff (12.0.1.66709, Alliance human mage) and missing in TDB.
-- Generated by stage 4 (er_stage4_sql.py). Phase per spawn is inferred from the sniff phase shifts, see the comment of each row;
-- rows marked "guess" were checked in stage 5. Map 2261 = Alliance Ship transport (transport-local coordinates).
-- GUIDs @CGUID+0..99999 and @OGUID+0..99999 belong to this file: it deletes the whole range before inserting.

SET @CGUID := 217500000000;
SET @OGUID := 217500000000;

DELETE FROM `creature` WHERE `guid` BETWEEN @CGUID+0 AND @CGUID+99999;

DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 217500000 AND 217500999;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 217500000 AND 217500999;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN @CGUID+0 AND @CGUID+99999;

DELETE FROM `gameobject` WHERE `guid` BETWEEN @OGUID+0 AND @OGUID+99999;

DELETE FROM `gameobject_addon` WHERE `guid` BETWEEN @OGUID+0 AND @OGUID+99999;
